// Simple decryption utility for paid content

const ENCRYPTION_KEY = 'yiming.weng';

/**
 * Decrypt content that was encrypted with XOR cipher + Base64
 * @param encryptedContent - The encrypted content
 * @returns - Decrypted plain text
 */
export function decrypt(encryptedContent: string): string {
  try {
    // Decode from Base64
    const binary = atob(encryptedContent);

    // XOR with key (same operation as encryption)
    let decrypted = '';
    for (let i = 0; i < binary.length; i++) {
      const keyChar = ENCRYPTION_KEY.charCodeAt(i % ENCRYPTION_KEY.length);
      const charCode = binary.charCodeAt(i) ^ keyChar;
      decrypted += String.fromCharCode(charCode);
    }

    // Decode from Base64
    return atob(decrypted);
  } catch (error) {
    console.error('Decryption failed:', error);
    return '';
  }
}
