import { useParams, Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import rehypeHighlight from 'rehype-highlight';
import { articles, getLocalizedContent } from '../data/articles';
import { decrypt } from '../utils/crypto';
import Paywall from '../components/Paywall';
import './BlogPost.css';
import 'highlight.js/styles/github-dark.css';

// Truncate content for paid articles (show first ~30%)
function truncateContent(content: string): string {
  const lines = content.split('\n');
  const truncateAt = Math.floor(lines.length * 0.3);
  const minLines = 20; // At least 20 lines
  const maxLines = 50; // At most 50 lines
  const targetLines = Math.max(minLines, Math.min(truncateAt, maxLines));
  return lines.slice(0, targetLines).join('\n');
}

export default function BlogPost() {
  const { t, i18n } = useTranslation();
  const { id } = useParams<{ id: string }>();
  const article = articles.find((a) => a.id === id);

  if (!article) {
    return (
      <div className="blog-post">
        <div className="container">
          <h1>{t('blog.articleNotFound')}</h1>
          <Link to="/blog">{t('blog.backToArticles')}</Link>
        </div>
      </div>
    );
  }

  const currentLang = i18n.language;
  const isPaid = article.isPaid || false;
  const encryptedContent = currentLang === 'zh' ? article.contentZh : article.contentEn;

  // Decrypt content if it's paid, otherwise use as-is
  const decryptedContent = isPaid ? decrypt(encryptedContent) : encryptedContent;
  const displayContent = isPaid ? truncateContent(decryptedContent) : decryptedContent;

  return (
    <div className="blog-post">
      <div className="container">
        <Link to="/blog" className="back-link">
          {t('blog.backToArticles')}
        </Link>

        <article className="article-content">
          <header className="article-header">
            <h1>{getLocalizedContent(article.title, currentLang)}</h1>
            <div className="article-meta">
              <span className="date">{article.date}</span>
              <span className="read-time">{t('blog.readTime', { count: article.readTime })}</span>
              {isPaid && <span className="paid-badge">付费内容</span>}
            </div>
            <div className="tags">
              {article.tags.map((tag) => (
                <span key={tag} className="tag">
                  {tag}
                </span>
              ))}
            </div>
          </header>

          <div className="article-body">
            <ReactMarkdown
              remarkPlugins={[remarkGfm]}
              rehypePlugins={[rehypeHighlight]}
            >
              {displayContent}
            </ReactMarkdown>
            {isPaid && <Paywall />}
          </div>
        </article>
      </div>
    </div>
  );
}
